113	function executionPrincipalsEqual(
114	  left: ParsedExecutionState["currentParticipant"] | null,
115	  right: ParsedExecutionState["currentParticipant"] | null,
116	) {
117	  if (!left || !right || left.type !== right.type) return false;
118	  return left.type === "agent" ? left.agentId === right.agentId : left.userId === right.userId;
