150	function summarizeIssueReferenceActivityDetails(input:
151	  | {
152	      addedReferencedIssues: ActivityIssueRelationSummary[];
153	      removedReferencedIssues: ActivityIssueRelationSummary[];
154	      currentReferencedIssues: ActivityIssueRelationSummary[];
155	    }
156	  | null
