171	function summarizeExecutionParticipants(
172	  policy: NormalizedExecutionPolicy | null,
173	  stageType: NormalizedExecutionPolicy["stages"][number]["type"],
174	): ActivityExecutionParticipant[] {
175	  const stage = policy?.stages.find((candidate) => candidate.type === stageType);
176	  return (
177	    stage?.participants.map((participant) => ({
178	      type: participant.type,
179	      agentId: participant.agentId ?? null,
180	      userId: participant.userId ?? null,
181	    })) ?? []
182	  );
183	}
